    n = min(left_w, right_w)

    def mode(values):
        return max(set(values), key=values.count)

    left_bg = mode([grid[r][c] for r in range(h) for c in range(left_w)])
    right_bg = mode([grid[r][c] for r in range(h) for c in range(sep + 1, w)])

    out = [[4] * n for _ in range(h)]
    for r in range(h):
        for c in range(n):
            if grid[r][c] != left_bg and grid[r][sep + 1 + c] != right_bg:
                out[r][c] = 3
