def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator is the uniform column nearest the center.
    candidates = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    sep = min(candidates, key=lambda c: abs(2 * c - (w - 1)))

    left_width = sep
    right_width = w - sep - 1
    width = min(left_width, right_width)

    def background(cells):
        counts = {}
        for value in cells:
            counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    left_bg = background([grid[r][c] for r in range(h) for c in range(left_width)])
    right_bg = background([grid[r][c] for r in range(h)
                           for c in range(sep + 1, w)])

    out = [[4] * width for _ in range(h)]
    for r in range(h):
        for c in range(width):
            if grid[r][c] != left_bg and grid[r][sep + 1 + c] != right_bg:
                out[r][c] = 3
    return out
